begin;
do $$ declare u uuid;begin
select created_by into u from public.aurora_workspaces where id='70edc9de-0513-4fef-84da-03fb2397f0cc';
if u is null then raise exception 'Organização de origem não encontrada';end if;
end $$;
create table aurora_private.demo_snapshot(id boolean primary key default true check(id),body jsonb not null);
alter table aurora_private.demo_snapshot enable row level security;
revoke all on aurora_private.demo_snapshot from public,anon,authenticated;
create function aurora_private.demo() returns jsonb language sql stable security definer set search_path='' as $$ select body from aurora_private.demo_snapshot where id=true $$;
create function public.aurora_demo() returns jsonb language sql security invoker set search_path='' as $$ select aurora_private.demo() $$;
revoke all on function aurora_private.demo(),public.aurora_demo() from public;
grant execute on function aurora_private.demo(),public.aurora_demo() to anon,authenticated;
commit;
